            return [expression]
        # function to split top level comma separated expressions inside braces
        def split_union(expr):
            parts = []
            brace_level = 0
            start = 0
            for i, ch in enumerate(expr):
                if ch == '{':
                    brace_level += 1
                elif ch == '}':
                    brace_level -= 1
                elif ch == ',' and brace_level == 0:
                    parts.append(expr[start:i])
                    start = i + 1
            parts.append(expr[start:])
            return parts

        # handle expression that starts and ends with braces as union
        if expression[0] == '{' and expression[-1] == '}':
            # check if outer braces enclose the whole group
            brace_level = 0
            for i, ch in enumerate(expression):
                if ch == '{':
                    brace_level += 1
                elif ch == '}':
                    brace_level -= 1
                if brace_level == 0 and i != len(expression)-1:
                    break
            else:
                # fully enclosed in outer braces
                inner = expression[1:-1]
                parts = split_union(inner)
                results = set()
                for part in parts:
                    res = self.braceExpansionII(part)
                    results |= set(res)
                return sorted(results)

        # splitting expression by concatenation
        # naive approach: split expression into segments which can be letters or braces
        segments = []
        i = 0
        while i < len(expression):
            if expression[i] == '{':
                brace_level = 1
                j = i+1
                while j < len(expression) and brace_level > 0:
                    if expression[j] == '{':
                        brace_level += 1
                    elif expression[j] == '}':
                        brace_level -= 1
                    j += 1
                segments.append(expression[i:j])
                i = j
            else:
                segments.append(expression[i])
                i += 1
        # now do cartesian product of results of segments
        from functools import reduce
        def cartesian_product(list1, list2):
            return [a+b for a in list1 for b in list2]

        results = ['']
        for segment in segments:
            part_res = self.braceExpansionII(segment)
            results = cartesian_product(results, part_res)
        return sorted(set(results))
